const webhook = $input.first().json;
const meetingId = webhook.query?.meetingId || webhook.params?.meetingId || null;
return [{ json: { meetingId } }];

const meetingId = $('Extract Meeting ID').first().json.meetingId;
const rows = $input.all().map((item) => item.json);
const meeting = rows[0];

if (!meetingId) {
  return [{ json: { error: true, statusCode: 400, message: 'Meeting ID is required', meetingId: null } }];
}

if (!meeting || !meeting.id) {
  return [{ json: { error: true, statusCode: 404, message: 'Meeting not found', meetingId } }];
}

if (!meeting.summary || !String(meeting.summary).trim()) {
  return [{ json: { error: true, statusCode: 400, message: 'No summary available', meetingId } }];
}

if (meeting.lastTimeEmailSent) {
  const last = new Date(meeting.lastTimeEmailSent);
  const diffSeconds = (Date.now() - last.getTime()) / 1000;
  if (diffSeconds < 60) {
    const remaining = Math.ceil(60 - diffSeconds);
    return [{ json: { error: true, statusCode: 429, message: `Please wait ${remaining} seconds`, cooldownRemaining: remaining, meetingId } }];
  }
}

function stripFences(text) {
  return String(text).replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
}

function tryParseSummary(text) {
  const cleaned = stripFences(text);
  try {
    const parsed = JSON.parse(cleaned);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : null;
  } catch {
    const start = cleaned.indexOf('{');
    if (start === -1) return null;
    let depth = 0;
    for (let i = start; i < cleaned.length; i++) {
      if (cleaned[i] === '{') depth++;
      else if (cleaned[i] === '}') {
        depth--;
        if (depth === 0) {
          try {
            return JSON.parse(cleaned.slice(start, i + 1));
          } catch {
            return null;
          }
        }
      }
    }
    return null;
  }
}

function formatBulletPoint(point) {
  if (typeof point === 'string') return point.trim();
  if (point && typeof point === 'object' && !Array.isArray(point)) {
    return Object.entries(point)
      .map(([key, value]) => `${key}: ${typeof value === 'string' ? value : String(value ?? '')}`)
      .join(' — ');
  }
  if (point == null) return '';
  return String(point).trim();
}

function bulletPoints(json) {
  const raw = json['Bolet Points'] ?? json['Bullet Points'];
  if (!Array.isArray(raw)) return [];
  return raw.map(formatBulletPoint).filter((item) => item.length > 0);
}

function formatSummaryHtml(summary) {
  const json = tryParseSummary(summary);
  if (!json) {
    return `<h3 style="color:#333;margin-top:0;text-align:right;border-bottom:2px solid #667eea;padding-bottom:10px;">خلاصه جلسه</h3><div style="color:#333;line-height:1.8;font-size:15px;text-align:right;white-space:pre-wrap;direction:rtl;">${String(summary)}</div>`;
  }

  let html = '<h3 style="color:#333;margin-top:0;text-align:right;border-bottom:2px solid #667eea;padding-bottom:10px;">خلاصه جلسه</h3>';

  if (json.Subject) {
    html += `<div style="margin-bottom:20px;"><h4 style="color:#555;margin:0 0 10px 0;text-align:right;font-size:16px;">موضوع:</h4><p style="color:#333;line-height:1.6;font-size:15px;text-align:right;margin:0;font-weight:bold;direction:rtl;">${json.Subject}</p></div>`;
  }

  if (json.Summary) {
    const isHtml = /<\/?[a-z][^>]*>/i.test(String(json.Summary));
    const body = isHtml
      ? `<div style="color:#333;line-height:1.8;font-size:15px;text-align:right;direction:rtl;">${json.Summary}</div>`
      : `<p style="color:#333;line-height:1.8;font-size:15px;text-align:right;margin:0;white-space:pre-wrap;direction:rtl;">${json.Summary}</p>`;
    html += `<div style="margin-bottom:20px;"><h4 style="color:#555;margin:0 0 10px 0;text-align:right;font-size:16px;">خلاصه:</h4>${body}</div>`;
  }

  const people = json['People in meetings'];
  if (Array.isArray(people) && people.length) {
    html += `<div style="margin-bottom:20px;"><h4 style="color:#555;margin:0 0 10px 0;text-align:right;font-size:16px;">افراد حاضر در جلسه:</h4><div style="text-align:right;direction:rtl;">${people.map((p) => `<span style="display:inline-block;background:#f0f0f0;padding:5px 10px;margin:2px;border-radius:15px;font-size:14px;color:#555;">${p}</span>`).join('')}</div></div>`;
  }

  const points = bulletPoints(json);
  if (points.length) {
    html += `<div style="margin-bottom:20px;"><h4 style="color:#555;margin:0 0 10px 0;text-align:right;font-size:16px;">نکات کلیدی:</h4><ul style="color:#333;line-height:1.8;font-size:15px;text-align:right;margin:0;padding-right:20px;direction:rtl;">${points.map((p) => `<li style="margin-bottom:8px;">${p}</li>`).join('')}</ul></div>`;
  }

  return html;
}

const summaryHtml = formatSummaryHtml(meeting.summary);
const htmlBody = `
<div dir="rtl" style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;padding:20px;direction:rtl;">
  <div style="background:linear-gradient(135deg,#667eea 0%,#764ba2 100%);color:white;padding:30px;border-radius:10px 10px 0 0;text-align:center;">
    <h1 style="margin:0;font-size:28px;">نشست یار</h1>
    <p style="margin:10px 0 0 0;opacity:0.9;">سیستم مدیریت جلسات</p>
  </div>
  <div style="background:#f8f9fa;padding:30px;border-radius:0 0 10px 10px;direction:rtl;">
    <div style="background:white;border:1px solid #dee2e6;border-radius:8px;padding:20px;margin:0;">${summaryHtml}</div>
  </div>
</div>`;

return [{
  json: {
    error: false,
    meetingId: meeting.id,
    title: meeting.title,
    email: meeting.email,
    userName: meeting.name || meeting.email,
    htmlBody,
  },
}];
